struct _vgsl_7961401a__Params {
  time: f32,
  texel: vec2f,
  accent: vec3f,
  ink: vec3f,
}

@group(0) @binding(0) var<uniform> params: _vgsl_7961401a__Params;

const _vgsl_7961401a__PI: f32 = 3.14159265359;



// 3D hash по ячейке
fn _vgsl_7961401a__hash31(p: vec3f) -> f32 {
  var q = fract(p * 0.3183099 + vec3f(0.71, 0.113, 0.419));
  q += dot(q, q.yzx + 19.19);
  return fract((q.x + q.y) * q.z);
}

@fragment
fn fs_main(@location(0) uv: vec2f) -> @location(0) vec4f {
  let t = params.time;
  var aspect = params.texel.y / params.texel.x;

  // центрируем и вытягиваем в квадрат
  var p = vec2f(uv.x * 2.0 - 1.0, (uv.y * 2.0 - 1.0) * aspect);
  p *= 1.35;

  let r = length(p);
  let ang = atan2(p.y, p.x);

  var col = params.ink * 0.0;

  // сфера: видимая шапка точек на вращающейся сфере
  let radius = 0.62;
  var spin = t * 0.45;

  // точки — сетка по широте/долготе
  let rings = 12;
  let segs = 34.0;

  var glow = 0.0;
  for (var i: i32 = 0; i < rings; i = i + 1) {
    let lat = (f32(i) + 0.5) / f32(rings) * _vgsl_7961401a__PI;
    let y3 = cos(lat);
    let ringR = sin(lat);
    for (var j: i32 = 0; j < 26; j = j + 1) {
      let lon = f32(j) / segs * 2.0 * _vgsl_7961401a__PI + spin + f32(i) * 0.31;
      let x3 = ringR * cos(lon);
      let z3 = ringR * sin(lon);

      // проекция на экран (только передняя полусфера)
      let sx = x3;
      let sy = y3; // экранный Y = мировая ось Y
      let sz = z3;

      // мерцание: часть точек «активируется» волной
      let band = sin(t * 1.6 - lat * 3.0);
      let seed = _vgsl_7961401a__hash31(vec3f(f32(i), f32(j), floor(t * 0.35)));
      let act = smoothstep(0.55, 1.0, band * 0.5 + 0.5 + seed * 0.35);

      let d = length(p - vec2f(sx, sy) * radius);
      let dotR = 0.006 + 0.005 * act;
      let dotMask = smoothstep(dotR, dotR * 0.25, d);

      // глубина: задняя полусфера тусклее
      let depth = smoothstep(-1.0, 1.0, sz);
      let dim = mix(0.18, 1.0, depth);

      glow += dotMask * dim * mix(0.35, 1.0, act);
    }
  }

  // мягкое ядро свечения
  let core = smoothstep(radius * 1.05, radius * 0.0, r) * 0.06;

  col += params.accent * (glow * 0.5);
  col += params.accent * core;

  // тонкое кольцо-меридиан: сканирующая линия
  let scan = fract(t * 0.22);
  let scanAng = scan * 2.0 * _vgsl_7961401a__PI;
  var sdir = vec2f(cos(scanAng), sin(scanAng));
  let proj = dot(p, sdir);
  let perp = abs(p.x * sdir.y - p.y * sdir.x);
  let ring = smoothstep(radius + 0.05, radius, length(p)) * smoothstep(radius - 0.18, radius - 0.02, length(p));
  let meridian = ring * smoothstep(0.035, 0.0, perp) * 0.65;
  col += params.accent * meridian;

  // гашение к краю, чтобы кадр не обрезался рамкой
  let vignette = smoothstep(1.5, 0.5, r);
  col *= vignette;

  // маска под текст: эллипс в центре — точки гаснут, заголовок читается чисто
  let te = vec2f(p.x / 0.66, (p.y + 0.10) / 0.40);
  let tmask = 1.0 - 0.85 * (1.0 - smoothstep(0.55, 1.3, length(te)));
  col *= tmask;

  return vec4f(col, 0.0);
}
